mapper.select:
SELECT r.*, u.username AS reporter_name, a.username AS handler_name FROM report r LEFT JOIN user u ON r.reporter_id = u.user_id LEFT JOIN user a ON r.handle_admin = a.user_id
AND r.status = #{status}
AND r.target_type = #{targetType}
ORDER BY r.report_id DESC

mapper.update:
UPDATE report
SET status = #{status},
    handle_admin = #{handleAdmin},
    handle_time = NOW(),
    handle_opinion = #{handleOpinion}
WHERE report_id = #{reportId}
